const sketch = (p5obj:any) => {
p5obj.setup = () => 
{
  p5obj.createCanvas( 1000, 1000 );
  p5obj.noLoop();
}

p5obj.draw = () => 
{
  p5obj.fill( 250 );
  p5obj.background( '#dfe0e2' );  //背景色を明るいグレーに設定
  p5obj.strokeWeight( 4 );  //線幅を4に設定

  for( let i: number = -300; i<=500; i+=80 )
  {
    p5obj.push();
    p5obj.translate( 500, 1000 );
    flower(0);
    p5obj.pop();
  }
}

//カスミソウの茎
const flower = (stem: number) => {
  if( stem<11 )
  {
    p5obj.stroke( 152, 174, 102 );
    p5obj.line( 0, 0, 0, -p5obj.height/10 );
    {
      p5obj.translate( 0, -p5obj.height/15 );
      p5obj.rotate( p5obj.random( -0.1, 0.1 ) );

      if( p5obj.random( 1.0 )<0.4 )
      {  
        p5obj.rotate( 0.4 );
        p5obj.scale( 0.7 );
        p5obj.push();
        flower( stem+1 );
        p5obj.pop();
        p5obj.rotate( -0.6 );
        p5obj.push();
        flower( stem+1 );
        p5obj.pop();
      }
      else
      {
        flower( stem );
      }
    }
  }
  
//カスミソウの花弁
  else
  {
    //花弁１
    p5obj.noStroke();
    p5obj.fill( 250, 250, 239 );
    p5obj.ellipse( 0, 0, p5obj.random(100,300), p5obj.random(100,300) );
    p5obj.stroke( 255 );
  
    //花弁２
    p5obj.fill( 247, 243, 237 );
    p5obj.ellipse( 30, 60, p5obj.random(70,90), p5obj.random(70,90) );
    
    //花弁３
    p5obj.fill( 249, 247, 239 );
    p5obj.ellipse( 100, 100, p5obj.random(60,80), p5obj.random(60,80) );
    
    //花弁４
    p5obj.fill( 250, 249, 254 );
    p5obj.ellipse( 500, 500, p5obj.random(100,120), p5obj.random(100,120) );
    
    //花弁５
    p5obj.fill( 232, 228, 222 );
    p5obj.ellipse( 900, 500, p5obj.random(30,50), p5obj.random(30,50) );
  }
}

};

export default sketch;
