const sketch = (p:any) => {
    p.setup = () => {
p.createCanvas(500, 500);      // Window Size
p.colorMode(p.RGB, 1.0); // RGB(0.0~1.0)
var fR, fG, fB;      // Window RGB
for (var iX=0; iX<p.width; iX++)
{
  for (var iY=0; iY<p.height; iY++)
  {
    /* Example */
    fR = p.sin(iX+10/30.0)*p.cos(iY/10.0);
    fG = p.cos(iX/30.0)*p.cos(iY+10/10.0);
    fB = p.tan(iX+20/40.0)*p.tan(iY+10/40.0);

    // draw pixel
    p.stroke(fR, fG, fB);
    p.point(iX, iY);
  }
}

  };
};

export default sketch;
