const sketch = (p5obj:any) => {
p5obj.setup = () => 
{
  p5obj.createCanvas( 1000, 1000 );
  p5obj.colorMode(p5obj.HSB, 360, 100, 100, 100 );  // カラーモード( HSB, 色相, 彩度, 輝度, 不透明度 )
  p5obj.background( 188, 90, 20 );  // 背景( 深緑色, 彩度90, 輝度20 )
  
  //花の座標はキャンバスの中心
  p5obj.translate( 500, 500 );
    //色彩設定
    for( let i: number = 45; i <= 80;  i++ ) // orange~yellow系の色
    {
      p5obj.blendMode( p5obj.SCREEN ); // 重なる部分が明るくなる
      p5obj.rotate( p5obj.PI/ 9 );  // 花弁は20度ずつ作られる
      
      p5obj.stroke( p5obj.random( i ), 100, 95, 10 ); // ( 色相はランダム, 彩度100, 輝度95, 不透明度10 )
      p5obj.strokeWeight( 1 );
      
      // 花の描画設定
      let kakudo: number = -90; // 反時計回りに90度回る
      let takasa: number = 140; // 高さは140で統一
      let X: number = 50;
      let Y: number = 50;
      Tree( kakudo, 110, X, Y );  // ( 90度(反時計回り), 高さ110, X50, Y50 )
      Tree( kakudo+5, takasa, X, Y );  // ( 85度(反時計回り), 高さ140 )
      Tree( kakudo+10, takasa, X, Y );  // ( 80度(反時計回り) )
      Tree( kakudo+15, takasa, X, Y );  // ( 75度(反時計回り) )
      Tree( kakudo+20, takasa, X, Y );  // ( 70度(反時計回り) )
      Tree( kakudo+25, takasa, X, Y );  // ( 65度(反時計回り) )
    }
 /*save("kadai_4.jpg");*/
}
 
 
// 花の形状設定
const Tree = (fAngle: number, fLength: number, fSX: number, fSY: number) => {
  // 終点座標
  let fEX: number = fLength*p5obj.cos( p5obj.radians( fAngle ) )+fSX;
  let fEY: number = fLength*p5obj.sin( p5obj.radians( fAngle ) )+fSY;
  // 軸の長さ
  p5obj.line( fSX, fSY, fEX, fEY );
  // 軸の他の線を描画
  if( fLength > 5 )  // 長さが5以上なら再帰終了
  {
    Tree( fAngle * 30, fLength*0.75, fEX, fEY ); // fAngle * 30
    Tree( fAngle = p5obj.hour()+p5obj.minute(), fLength*0.75, fEX, fEY ); // fAngle = 時＋分によって決定する
    console.log(fAngle);
  }
}

};

export default sketch;
