const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
var sx=0, sy=0; //螟画焚縺ｮ螳｣險・域ｭ｣譁ｹ蠖｢縺ｮ蟾ｦ荳街縲〆蠎ｧ讓呻ｼ・
var px, py; //螟画焚縺ｮ螳｣險・域ｭ｣譁ｹ蠖｢縺ｮ荳ｭ蠢・・繧ｺ繝ｬX,Y蠎ｧ讓呻ｼ・
for (var i=0; i<10; i++)
{
  sx=i*50; //豁｣譁ｹ蠖｢縺ｮ髢句ｧ句慍轤ｹ縺ｮX蠎ｧ讓吶ｒ險育ｮ・
  for (var j=0; j<10; j++)
  {
    sy=j*50; //豁｣譁ｹ蠖｢縺ｮ髢句ｧ句慍轤ｹ縺ｮY蠎ｧ讓吶ｒ險育ｮ・
    px=p5obj.random(5);//荵ｱ謨ｰ縺ｧ繧ｺ繝ｬ繧呈ｱゅａ繧・
    py=p5obj.random(5);
    for (var k=0; k<10; k++)
    {
      p5obj.rect(sx+px*k, sy+py*k, 50-(k*5), 50-(k*5));
    }
  }
}

  };
};

export default sketch;
