const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas( 500, 500 );
p5obj.colorMode(p5obj.HSB, 100 );
p5obj.background( 0 );
p5obj.translate( 250, 250 );

p5obj.strokeWeight( 0.75 );
p5obj.noFill();

for (var iX=0; iX<500; iX+=2 )
{
  p5obj.rotate( 2 );
  p5obj.stroke( 40+iX*iX/2500, 100, 100 );  //濶ｲ逶ｸ繧堤ｷ代°繧牙､牙喧縺吶ｋ繧医≧縺ｫ隱ｿ謨ｴ
  p5obj.ellipse( iX/1.4, 0, iX/1.5, iX/6 );  //荳ｭ螟ｮ縺九ｉ髮｢繧後ｋ縺ｻ縺ｩ逶ｴ蠕・′螟ｧ縺阪￥縺ｪ繧九ｈ縺・↓隱ｿ謨ｴ
}

  };
};

export default sketch;
