const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.colorMode(p5obj.RGB, 255, 255, 255, 100);
p5obj.background(0, 0, 0);
var a =30;//蜈ｭ隗貞ｽ｢蟆上・霎ｺ
var b =15*p5obj.sqrt(3);//鬮倥＆
var c =60;//蜈ｭ隗貞ｽ｢螟ｧ縺ｮ霎ｺ
var d =30*p5obj.sqrt(3);//鬮倥＆
for (var y=0; y<530; y+=a)//驥阪↑繧九ｈ縺・★繧峨☆
{
  for (var x=0; x<=530; x+=d)
  {
    p5obj.strokeWeight(p5obj.random(1, 2));//邱壼､ｪ縺・
    p5obj.stroke(250, 250, 250, 100);//逋ｽ邱・
    p5obj.quad(0+x, 0+y, b+x, -15+y, d+x, 0+y, b+x, 15+y);
    p5obj.line(0+x, 0+y, 0+x, a+y);
    p5obj.line(b+x, -15+y, b+x, 15+y);
    p5obj.noStroke();
    p5obj.fill(p5obj.random(0, 240), p5obj.random(0, 40), p5obj.random(0, 30), 80);//襍､蟇・ｊ繝ｩ繝ｳ繝繝
    p5obj.beginShape();//蜈ｭ隗貞ｽ｢蟆・
    p5obj.vertex(0+x, 0+y);
    p5obj.vertex(b+x, -15+y);
    p5obj.vertex((2*b)+x, 0+y);
    p5obj.vertex((2*b)+x, a+y);
    p5obj.vertex(b+x, 45+y);
    p5obj.vertex(0+x, a+y);
    p5obj.endShape(p5obj.CLOSE);
  }
}
p5obj.translate(-b, 15);//蜈ｭ隗貞ｽ｢蟆上→莠､莠偵↓縺吶ｋ
for (var t=0; t<530; t+=60)
{
  for (var p=0; p<=530; p+=(4*b)-1.5)//蜈ｭ隗貞ｽ｢縺ｨ菴咲ｽｮ縺後★繧後ｋ縺溘ａ蠕ｮ隱ｿ謨ｴ
  {
    p5obj.fill(p5obj.random(0, 0), p5obj.random(30, 50), p5obj.random(90, 120), p5obj.random(0, 60));
    p5obj.beginShape();//蜈ｭ隗貞ｽ｢螟ｧ
    p5obj.vertex(0+p, 0+t);
    p5obj.vertex(d+p, -30+t);
    p5obj.vertex((2*d)+p, 0+t);
    p5obj.vertex((2*d)+p, c+t);
    p5obj.vertex(d+p, 90+t);
    p5obj.vertex(0+p, c+t);
    p5obj.endShape(p5obj.CLOSE);
  }
}

  };
};

export default sketch;
