const sketch = (p:any) => {
    p.setup = () => {
p.createCanvas(500, 500);      // Window Size
p.colorMode(p.RGB, 1.0); // RGB(0.0~1.0)
var fR, fG, fB;      // Window RGB
for (var iX=0; iX<p.width; iX++)
{
  for (var iY=0; iY<p.height; iY++)
  {
    /* Example */
    fR = p.sin(iY/10.0+p.cos(iX/20.0))/p.sin(iX);
    fG = p.sin(iX/10.0+p.sin(iY/20.0))/p.sin(iY);
    fB = p.sin(iX/10.0*p.cos(iY/20.0))+p.sin(iX);
    // draw pixel
    p.stroke(fR, fG, fB);
    p.point(iX, iY);
  }
}

  };
};

export default sketch;
