const sketch = (p5obj:any) => {
/* モードA/Bの切り替え */
let modeA: boolean = true;

/* モードAの変数 */
let row: number = 0;
let col: number = 0;

let rowSize: number = 0;
let colSize: number = 0;


/* A/B共通の変数 */
let railNum: number = 0;

let x_rail: number[];
let y_rail: number[];

let railColors: any[] = [ 
  p5obj.color(200,50,50), p5obj.color(50,180,80), p5obj.color(0,80,179),
  p5obj.color(243,152,0), p5obj.color(147,112,219), p5obj.color(60,179,113),
  p5obj.color(199,100,66), p5obj.color(0,161,233), p5obj.color(227,215,163), 
  p5obj.color(0,155,159), p5obj.color(234,85,50), p5obj.color(233,83,136),
 ];

let railMin: number = 0;

let railMax: number = 0;

let xdif: number = 0;

let ydif: number = 0;

let xScale: number = 0;

let yScale: number = 0;


let xoff: number = 0;

let xadd: number = 0;

let yadd: number = 0;



p5obj.setup = () =>  {
  p5obj.createCanvas(1000,1000);
  
  if (modeA) {
    /* モードAの変数を初期化 */
    rowSize = 25;
    colSize = 25;
    row = p5obj.width/rowSize;
    col = p5obj.height/colSize;
    
    railNum = railColors.length*5;
    railMin = 10;
    railMax = 30;
    xdif = 5;
    ydif = 5;
    xScale = row;
    yScale = col;
    
  } else {
    /* モードBの変数を初期化 */
    railNum = railColors.length*4;
    railMin = 5;
    railMax = 15;
    xdif = 50;
    ydif = 50;
    xScale = p5obj.width;
    yScale = p5obj.height;
  }
  
  xoff = 0;
  xadd = 0;
  yadd = 0;
  
  x_rail = new Array<number>(railNum);
  y_rail = new Array<number>(railNum);
  for (let i: number = 0;i<railNum;i++) {
    x_rail[i] = 0;
    y_rail[i] = 0;
  }
  
  p5obj.noLoop();
}

p5obj.draw = () =>  {
  p5obj.background(255);
 
  for (let i: number = 0;i<x_rail.length;i++) {
    /* 路線体の始点の位置を定める */
    x_rail[i] = p5obj.noise(i+p5obj.random(0,10))*xScale;
    y_rail[i] = p5obj.noise(i+p5obj.random(0,10))*yScale;
    
    /* 始点を格子上に配置する(モードA) */
    if (modeA) {
      x_rail[i] = p5obj.round(x_rail[i])*rowSize;
      y_rail[i] = p5obj.round(y_rail[i])*colSize;
    }
    
    /* １体の路線体を描画する */
    recursiveRail(x_rail[i],y_rail[i],p5obj.round(p5obj.random(railMin,railMax)),p5obj.color(railColors[i%railColors.length],35));
  }
  
  recursiveLight(p5obj.ceil(p5obj.dist(0,0,p5obj.width,p5obj.height)));
}

/* 視界を描画する再帰関数 */
const recursiveLight = (n: number) => {
  p5obj.noFill();
  p5obj.strokeWeight(2);
  
  /* 視界の明るさを表現する */
  p5obj.stroke(0,p5obj.pow(1.005,n));
  p5obj.circle(p5obj.width/2,p5obj.height/2,n);
  
  /* 直径を少しずつ絞り円を描いていく */
  if(n>0) {
    recursiveLight(n-1);
  }
}

/* 路線体を描画する再帰関数 */
const recursiveRail = (x: number, y: number, n: number, c: any) => {

  /* 次に描く点の位置を決定する */
  xadd = xdif*p5obj.noise(xoff)*p5obj.pow(-1,p5obj.round(p5obj.random(0,1)));
  yadd = ydif*p5obj.noise(xoff+10)*p5obj.pow(-1,p5obj.round(p5obj.random(0,1)));
  
  /* 次点を格子上に配置する(モードA) */
  if (modeA) {
    xadd = p5obj.round(xadd)*rowSize;
    yadd = p5obj.round(yadd)*colSize;
  }
  
  p5obj.stroke(c);
  p5obj.noFill();
  
  /* 曲線の描画 */
  p5obj.strokeWeight(p5obj.noise(xoff)*5);
  p5obj.bezier(x,y,x+xadd,y,x,y+yadd,x+xadd,y+yadd);
  
  
  /* 始点と次点の描画 */
  p5obj.fill(255);
  p5obj.strokeWeight(p5obj.noise(xoff+2)*5);
  p5obj.circle(x,y,p5obj.noise(xoff)*10);
  
  p5obj.strokeWeight(p5obj.noise(xoff+4)*5);
  p5obj.circle(x+xadd,y+yadd,p5obj.noise(xoff+1)*10);
  
  
  /* 「・ー・」を数珠のように繋げていく */
  if (n>0) {
    recursiveRail(x+xadd,y+yadd,n-1,c);
    xoff += p5obj.random(0,1);
  }
  
}

};

export default sketch;
