const sketch = (p:any) => {
    p.setup = () => {
p.createCanvas(500, 500);      // Window Size
p.colorMode(p.RGB, 1.0); // RGB(0.0~1.0)
var fR, fG, fB;      // Window RGB
for (var iX=0; iX<p.width; iX++)
{
  for (var iY=0; iY<p.height; iY++)
  {
    /* Example */
    fR = 0.0;
    fG = p.tan(p.pow(iX*2, 2))/0.4*p.tan(p.pow(iY*2, 2))/0.2;
    fB = p.sin(p.pow(iX*2, 2))/0.2*p.sin(p.pow(iY*2, 2))/0.4;

    // draw pixel
    p.stroke(fR, fG, fB);
    p.point(iX, iY);
  }
}

  };
};

export default sketch;
